script:
(function () {
  'use strict';
  // Monthly vs accelerated biweekly / weekly mortgage payments.
  //   Monthly payment M = L * i / (1 - (1 + i)^-n), i = rate / 12 (M = L / n at 0%).
  //   Balance after k monthly payments: B = L(1+i)^k - M((1+i)^k - 1)/i, computed by a loop.
  //   Accelerated biweekly: M / 2 every two weeks (26 a year), interest at rate / 26 per period.
  //   Accelerated weekly: M / 4 every week (52 a year), interest at rate / 52 per period.
  //   Monthly + 1/12: M * 13 / 12 each month, i.e. one extra monthly payment a year.
  //   Fees (setup + per payment) apply to the biweekly and weekly plans only.
  // Verified in Node (scratchpad tests/m5): $300,000 at 6.5% for 30 yrs = $1,896.20/mo, total
  //   interest $382,633.47 (closed form); biweekly payoff count matches the closed form
  //   n = -ln(1 - B*j/P) / ln(1 + j) with j = 0.065/26, P = M/2 (rounded up); every plan ends at a
  //   zero balance; 0% rate gives no interest and the plans differ only in time; balance after 5 years
  //   matches the closed-form remaining-balance formula; no NaN/Infinity on blank or bad input.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function monthlyPayment(loan, i, n) {
    if (n <= 0 || loan <= 0) return 0;
    if (i === 0) return loan / n;
    return loan * i / (1 - Math.pow(1 + i, -n));
  }

  // Pay `pay` each period at periodic rate i until the balance is gone.
  // Records the balance at the end of each year (every `perYear` periods).
  function run(balance, i, pay, perYear) {
    var bal = balance, interest = 0, periods = 0, yearEnd = [];
    while (bal > 0.005 && periods < 100 * perYear) {
      var intr = bal * i;
      var principal = Math.min(pay - intr, bal);
      if (principal <= 0) break;
      bal -= principal;
      if (bal < 0.005) bal = 0;
      interest += intr;
      periods++;
      if (periods % perYear === 0 || bal === 0) yearEnd[Math.ceil(periods / perYear) - 1] = bal;
    }
    return { periods: periods, interest: interest, years: periods / perYear, yearEnd: yearEnd };
  }

  function duration(months) {
    months = Math.max(0, Math.round(months));
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function clearResults() {
    ['bwBiPay', 'bwTimeSaved', 'bwInterestSaved', 'bwNetSaved', 'bwMonthlyPay', 'bwBalance',
     'bwRemaining', 'bwFees'].forEach(function (id) { setText(id, '–'); });
    el('bwPlans').innerHTML = '';
    el('bwYears').innerHTML = '';
  }

  function update() {
    var amount = read('bwAmount'), rate = read('bwRate'), term = read('bwTerm'),
        paid = read('bwPaid', true), setup = read('bwSetupFee', true), perFee = read('bwPerFee', true);
    var error = el('bwError'), msg = '';
    if (isNaN(amount) || amount <= 0) msg = 'Enter an original loan amount greater than $0.';
    else if (isNaN(rate) || rate < 0 || rate > 30) msg = 'Enter an interest rate from 0% to 30%.';
    else if (isNaN(term) || term < 1 || term > 50 || term % 1 !== 0) msg = 'Enter a loan term of 1 to 50 whole years.';
    else if (isNaN(paid) || paid < 0 || paid % 1 !== 0 || paid >= term) msg = 'Years already paid must be a whole number less than the loan term.';
    else if ([setup, perFee].some(function (v) { return isNaN(v) || v < 0; })) msg = 'Fees cannot be negative.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var r = rate / 100, iM = r / 12, n = term * 12;
    var M = monthlyPayment(amount, iM, n);
    var bal = amount;
    for (var k = 0; k < paid * 12; k++) bal -= M - bal * iM;
    if (bal < 0.005) bal = 0;

    var plans = [
      { name: 'Monthly (current)', pay: M, per: 12, res: run(bal, iM, M, 12), fees: false },
      { name: 'Accelerated biweekly', pay: M / 2, per: 26, res: run(bal, r / 26, M / 2, 26), fees: true },
      { name: 'Accelerated weekly', pay: M / 4, per: 52, res: run(bal, r / 52, M / 4, 52), fees: true },
      { name: 'Monthly + 1/12 extra', pay: M * 13 / 12, per: 12, res: run(bal, iM, M * 13 / 12, 12), fees: false }
    ];
    var base = plans[0].res;
    plans.forEach(function (p) {
      p.feeTotal = p.fees && p.res.periods > 0 ? setup + perFee * p.res.periods : 0;
      p.saved = base.interest - p.res.interest;
    });
    var bi = plans[1];

    setText('bwBiPay', money.format(M / 2));
    setText('bwTimeSaved', duration((base.years - bi.res.years) * 12));
    setText('bwInterestSaved', money.format(Math.max(0, bi.saved)));
    setText('bwNetSaved', money.format(bi.saved - bi.feeTotal));
    setText('bwMonthlyPay', money.format(M));
    setText('bwBalance', money.format(bal));
    setText('bwRemaining', duration(base.years * 12));
    setText('bwFees', money.format(bi.feeTotal));

    el('bwPlans').innerHTML = plans.map(function (p) {
      return '<tr><th scope="row">' + p.name + '</th><td>' + money.format(p.pay) + '</td><td>' + money0.format(p.pay * p.per) +
        '</td><td>' + duration(p.res.years * 12) + '</td><td>' + money.format(p.res.interest) + '</td><td>' +
        money.format(Math.max(0, p.saved)) + '</td><td>' + money.format(p.feeTotal) + '</td></tr>';
    }).join('');

    var html = [], yearsShown = base.yearEnd.length;
    for (var y = 0; y < yearsShown; y++) {
      var mb = base.yearEnd[y], bb = y < bi.res.yearEnd.length ? bi.res.yearEnd[y] : 0;
      html.push('<tr><td>' + (paid + y + 1) + '</td><td>' + money.format(mb) + '</td><td>' + money.format(bb) +
        '</td><td>' + money.format(mb - bb) + '</td></tr>');
    }
    el('bwYears').innerHTML = html.join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('bwForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
